// Backfills ratehawk_image_1..50 / ratehawk_image_1_category..50_category on
// hotels from scripts/ratehawk/output/matched-hotel-images.jsonl (already
// generated by extract-images-for-matched.mjs, one line per confirmed match,
// direct hid->oltra_id join per line — no index-based joins).
//
// Preserves Ratehawk's native images_ext order verbatim: image[0] -> _1
// (their own first-returned image, the closest thing to a "hero" signal
// Ratehawk provides — see CLAUDE.md §27). URLs are stored unresolved, with
// the {size} template placeholder intact.
//
// Skips every image in excluded-gallery-images.json (galleryExclusions.mjs):
// floor plans and renderings taken out on purpose on 2026-10-07 must not come
// back with a re-import. Slots past the last image written are cleared, so a
// shorter gallery cannot leave an old image behind in its tail.
//
// Note: this writes ETG's order, which undoes the curated hero order of
// 2026-10-06 (.claude/rules/hotel-data.md).
//
// Defaults to dry-run. --confirm to write. --only <oltra_id> for a single
// hotel. --limit N to cap how many hotels are processed.
//
// Usage (from hotels-beta/):
//   node scripts/ratehawk/apply-ratehawk-images.mjs [--confirm] [--only <id>] [--limit N]
import fs from "fs/promises";
import dotenv from "dotenv";
import { isExcludedGalleryImage, excludedGalleryImageCount } from "./galleryExclusions.mjs";
dotenv.config({ path: ".env.local" });

const DIRECTUS_URL = process.env.DIRECTUS_URL?.replace(/\/+$/, "");
const DIRECTUS_TOKEN = process.env.DIRECTUS_TOKEN;
if (!DIRECTUS_URL) throw new Error("Missing DIRECTUS_URL in environment");
if (!DIRECTUS_TOKEN) throw new Error("Missing DIRECTUS_TOKEN in environment");

const INPUT_PATH = "scripts/ratehawk/output/matched-hotel-images.jsonl";
const MAX_IMAGES = 50;

function parseArgs(argv) {
  const args = { confirm: false, only: null, limit: null };
  for (let i = 2; i < argv.length; i++) {
    if (argv[i] === "--confirm") args.confirm = true;
    else if (argv[i] === "--only") args.only = argv[++i];
    else if (argv[i] === "--limit") args.limit = Number(argv[++i]);
  }
  return args;
}

function galleryImages(record) {
  return record.images_ext.filter((image) => !isExcludedGalleryImage(record.oltra_id, image.url));
}

function buildPayload(record) {
  const payload = {};
  const images = galleryImages(record).slice(0, MAX_IMAGES);
  for (let n = 1; n <= MAX_IMAGES; n++) {
    const image = images[n - 1];
    payload[`ratehawk_image_${n}`] = image ? image.url : null;
    payload[`ratehawk_image_${n}_category`] = image ? image.category_slug ?? null : null;
  }
  return payload;
}

async function patchHotel(oltraId, payload) {
  const res = await fetch(`${DIRECTUS_URL}/items/hotels/${oltraId}`, {
    method: "PATCH",
    headers: {
      Authorization: `Bearer ${DIRECTUS_TOKEN}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Directus ${res.status}: ${text}`);
  }
  return res.json();
}

async function main() {
  const args = parseArgs(process.argv);

  const raw = await fs.readFile(INPUT_PATH, "utf8");
  let records = raw
    .trim()
    .split("\n")
    .map((line) => JSON.parse(line));

  if (args.only) records = records.filter((r) => String(r.oltra_id) === String(args.only));
  if (Number.isFinite(args.limit) && args.limit > 0) records = records.slice(0, args.limit);

  console.log(`Mode: ${args.confirm ? "LIVE" : "DRY RUN"}`);
  console.log(`Hotels to process: ${records.length}`);
  console.log("--------------------------------------------------");

  let updated = 0;
  let skippedNoImages = 0;
  let failed = 0;
  let excludedSkipped = 0;
  console.log(`Excluded gallery images on file: ${excludedGalleryImageCount()}`);

  for (const record of records) {
    // Integrity guard: the payload we're about to write must belong to the
    // hid/oltra_id pair we're iterating over right now, never a stray from
    // a mismatched index elsewhere in the pipeline.
    if (!record.oltra_id || !record.hid) {
      console.error(`SKIP malformed record: ${JSON.stringify(record).slice(0, 200)}`);
      failed++;
      continue;
    }

    const payload = buildPayload(record);
    const imageCount = galleryImages(record).length;
    const excludedHere = record.images_ext.length - imageCount;
    excludedSkipped += excludedHere;

    console.log(
      `${record.oltra_id} | hid=${record.hid} | ${record.name} | ${imageCount} image(s)${
        imageCount > MAX_IMAGES ? ` (truncated to ${MAX_IMAGES})` : ""
      }${excludedHere ? `, ${excludedHere} excluded` : ""}`
    );

    if (imageCount === 0) {
      skippedNoImages++;
      console.log("  no images — nothing to write");
      console.log("--------------------------------------------------");
      continue;
    }

    if (!args.confirm) {
      const preview = Object.fromEntries(Object.entries(payload).slice(0, 4));
      console.log("  DRY RUN payload (first 2 image/category pairs):", JSON.stringify(preview));
      updated++;
      console.log("--------------------------------------------------");
      continue;
    }

    try {
      await patchHotel(record.oltra_id, payload);
      updated++;
      console.log("  UPDATED");
    } catch (error) {
      failed++;
      console.error(`  FAILED: ${error.message}`);
    }

    console.log("--------------------------------------------------");
  }

  console.log("DONE");
  console.log(`Updated (or would update):  ${updated}`);
  console.log(`No images, skipped:         ${skippedNoImages}`);
  console.log(`Failed:                     ${failed}`);
  console.log(`Excluded images skipped:    ${excludedSkipped}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
